import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Database connection pool managed by container
    private DataSource getDataSource() throws Exception {
        javax.naming.InitialContext ctx = new javax.naming.InitialContext();
        return (DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Validate session exists
        HttpSession session = req.getSession(false);
        if (session == null || session.getAttribute("user") == null) {
            resp.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }

        String username = (String) session.getAttribute("user");
        log.info("Report request from user=" + username + " type=" + reportType);

        // Build query based on report type
        String query;
        if ("summary".equals(reportType)) {
            query = "SELECT department, COUNT(*) as cnt, SUM(amount) as total " +
                    "FROM transactions WHERE tx_date BETWEEN '" + startDate + 
                    "' AND '" + endDate + "'";
            if (department != null && !department.isEmpty()) {
                query += " AND department = '" + department + "'";
            }
            query += " GROUP BY department ORDER BY total DESC";
        } else if ("detail".equals(reportType)) {
            query = "SELECT id, department, amount, description, tx_date " +
                    "FROM transactions WHERE tx_date BETWEEN '" + startDate +
                    "' AND '" + endDate + "'";
            if (department != null && !department.isEmpty()) {
                query += " AND department = '" + department + "'";
            }
            query += " ORDER BY tx_date DESC LIMIT 500";
        } else {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid report type");
            return;
        }

        // Execute and return results
        try (Connection conn = getDataSource().getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\": ");
                    if (rs.getObject(i) instanceof Number) {
                        json.append(rs.getObject(i));
                    } else {
                        json.append("\"").append(String.valueOf(rs.getObject(i))
                            .replace("\"", "\\\"")).append("\"");
                    }
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (Exception e) {
            log.severe("Query failed: " + e.getMessage());
            // Return generic error - don't leak SQL details
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, 
                          "Report generation failed");
        }
    }
}
